/* =====================================================================
   02_resetear_productosdb.sql  -  Laboratorio 4 (CRUD con imágenes)
   ---------------------------------------------------------------------
   Resetea COMPLETAMENTE productosdb:
     1. Elimina la base de datos entera (cierra las conexiones abiertas,
        incluida la aplicación si está corriendo).
     2. La vuelve a crear desde cero con la tabla productos.
     3. Carga los 3 PRIMEROS productos del volcado del laboratorio
        (Teclado, Mouse y Portátil con su imagen) -> folios 1, 2 y 3.
        El siguiente producto que se agregue tendrá el folio 4.

   Uso: SSMS -> abrir este archivo -> Ejecutar (F5)
        o:  sqlcmd -S Mateo -E -C -f 65001 -i 02_resetear_productosdb.sql
   ===================================================================== */

SET NOCOUNT ON;
GO

USE master;
GO

/* ---------- 1) Eliminar la base de datos completa ---------- */
IF DB_ID(N'productosdb') IS NOT NULL
BEGIN
    -- Desconecta a cualquier usuario/aplicación conectada para poder borrarla
    ALTER DATABASE productosdb SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE productosdb;
    PRINT N'Base de datos productosdb eliminada.';
END
GO

/* ---------- 2) Crear la base de datos desde cero ---------- */
CREATE DATABASE productosdb;
GO

USE productosdb;
GO

CREATE TABLE dbo.productos (
    id       INT IDENTITY(1, 1) NOT NULL CONSTRAINT PK_productos PRIMARY KEY,
    nombre   NVARCHAR(100)  NOT NULL,
    precio   DECIMAL(10, 2) NOT NULL,
    cantidad INT            NOT NULL,
    imagen   VARBINARY(MAX) NULL      -- equivalente al LONGBLOB de MySQL
);
GO

/* ---------- 3) Cargar los 3 primeros productos ---------- */
-- Imágenes PNG del volcado original (hex -> VARBINARY)
-- @img_agregar: ícono "agregar imagen" (21,582 bytes), usado por los folios 3, 4 y 5
DECLARE @img_agregar VARBINARY(MAX) = ;

BEGIN TRANSACTION;

SET IDENTITY_INSERT dbo.productos ON;

INSERT INTO dbo.productos (id, nombre, precio, cantidad, imagen) VALUES
    (1, N'Teclado',  20.00,  2, NULL),          -- sin imagen
    (2, N'Mouse',    15.70,  2, NULL),          -- sin imagen
    (3, N'Portátil', 700.70, 2, @img_agregar);

SET IDENTITY_INSERT dbo.productos OFF;

COMMIT TRANSACTION;

PRINT N'productosdb reseteada con 3 productos.';
GO

-- Verificación
SELECT id, nombre, precio, cantidad, DATALENGTH(imagen) AS bytes_imagen
FROM dbo.productos
ORDER BY id;
GO
